import Foundation

/// What to do with a pasteboard change, decided from its declared types only (pure).
public enum ClipboardPolicy {
    /// Types a password manager or another app sets to say "do not record this" (nspasteboard.org).
    public static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    public enum Source: Equatable, Sendable { case png, tiff }

    public enum Decision: Equatable, Sendable {
        case skip              // concealed/transient, or nothing usable
        case text
        case image(Source)
    }

    /// Ignored types win over everything; text wins over an image; PNG wins over TIFF.
    public static func decide(types: Set<String>, hasText: Bool) -> Decision {
        guard types.isDisjoint(with: ignoredTypes) else { return .skip }
        if hasText { return .text }
        if types.contains("public.png") { return .image(.png) }
        if types.contains("public.tiff") { return .image(.tiff) }
        return .skip
    }

    /// Whether the change count moved (a poll has work to do).
    public static func changed(current: Int, last: Int) -> Bool { current != last }

    /// An encoded picture is only added if no other copy happened while it was being encoded.
    public static func isStillCurrent(count: Int, last: Int) -> Bool { count == last }

    /// Raw pasteboard data larger than this is not even decoded.
    public static func isAcceptableImageSize(_ bytes: Int, limit: Int) -> Bool { bytes <= limit }
}
